//! Timer drivers
//!
//! - [`Timer2`], [`Timer3`]: general-purpose timers (TIM2, TIM3) with
//!   prescaler/period configuration, counter access and update-interrupt
//!   support. Both are generated by the `impl_timer!` macro.
//! - [`Timer1Pwm`], [`Timer2Pwm`]: PWM drivers for the full-featured TIM1 and
//!   TIM2 timers (4 channels, complementary outputs, dead-time, break and
//!   main-output enable). Both are generated by the `impl_timer_pwm!` macro.
//! - [`Timer1Capture`], [`Timer2Capture`]: input-capture drivers (edge
//!   capture and PWM-input frequency/duty measurement), generated by the
//!   `impl_timer_capture!` macro.
//! - [`Timer1Encoder`], [`Timer2Encoder`]: quadrature encoder interface
//!   drivers, generated by the `impl_timer_encoder!` macro.
//!
//! # Example
//!
//! ```ignore
//! use ch32x035::{Rcc, Clocks, timer::Timer3};
//!
//! let mut rcc = Rcc::new(dp.RCC);
//! let clocks = Clocks::new(&rcc);
//! let mut tim = Timer3::init(dp.TIM3, &mut rcc, clocks);
//! tim.set_prescaler(47999); // 1 kHz tick @ 48 MHz
//! tim.set_period(999);
//! tim.start();
//! ```

use crate::Steal;
use crate::pac;
use crate::rcc::{Clocks, Rcc};
use crate::reset::Resettable;

/// Generate a general-purpose timer driver (`Timer2`, `Timer3`).
///
/// Uses the registers shared by TIM2 and TIM3: `CTLR1` (CEN), `PSC`, `ATRLR`,
/// `CNT`, `INTFR` (UIF) and `DMAINTENR` (UIE).
macro_rules! impl_timer {
    ($name:ident, $periph:ty, $module:ident) => {
        /// General-purpose timer driver
        pub struct $name {
            tim: $periph,
            #[allow(dead_code)]
            clocks: Clocks,
        }

        impl $name {
            /// Create a new timer driver, resetting and clock-enabling the
            /// peripheral.
            pub fn init(tim: $periph, rcc: &mut Rcc, clocks: Clocks) -> Self {
                tim.init(rcc);
                Self { tim, clocks }
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                    clocks: unsafe { Clocks::steal() },
                })
            }

            /// Set the prescaler value (`PSC`).
            ///
            /// The counter clock is `PCLK1 / (PSC + 1)`.
            #[inline(always)]
            pub fn set_prescaler(&mut self, psc: u16) {
                self.tim.psc.write_psc(psc as u32);
            }

            /// Set the auto-reload (period) value (`ATRLR`).
            #[inline(always)]
            pub fn set_period(&mut self, period: u16) {
                self.tim.atrlr.write_atrlr(period as u32);
            }

            /// Start the counter.
            #[inline(always)]
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            #[inline(always)]
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Read the current counter value.
            #[inline(always)]
            pub fn count(&self) -> u16 {
                self.tim.cnt.cnt() as u16
            }

            /// Clear the update interrupt flag.
            #[inline(always)]
            pub fn clear_update_flag(&mut self) {
                self.tim.intfr.write_bits(pac::$module::Intfr::UIF);
            }

            /// Check whether the update interrupt flag is set.
            #[inline(always)]
            pub fn is_update_flag(&self) -> bool {
                self.tim.intfr.read_bits() & pac::$module::Intfr::UIF != 0
            }

            /// Enable the update interrupt.
            #[inline(always)]
            pub fn enable_update_interrupt(&mut self) {
                self.tim.dmaintenr.set_uie();
            }

            /// Disable the update interrupt.
            #[inline(always)]
            pub fn disable_update_interrupt(&mut self) {
                self.tim.dmaintenr.clr_uie();
            }

            /// Consume the driver and return the underlying peripheral.
            #[inline(always)]
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer!(Timer2, pac::TIM2, tim2);
impl_timer!(Timer3, pac::TIM3, tim3);

/// Generate a 4-channel PWM driver for a full-featured timer (TIM1, TIM2).
///
/// Both TIM1 and TIM2 expose the same register layout: `CHCTLR1/2_Output`
/// (OCxM/OCxPE/CCxS), `CCER` (CCxE), `CHxCCR`, `BDTR` (MOE) and the counter
/// group.
macro_rules! impl_timer_pwm {
    ($name:ident, $periph:ty) => {
        /// 4-channel PWM driver for an advanced/general timer
        pub struct $name {
            tim: $periph,
        }

        impl $name {
            /// Create a new PWM driver, resetting and clock-enabling the
            /// peripheral. The counter is configured for PWM with the given
            /// prescaler and auto-reload values.
            pub fn init(tim: $periph, rcc: &mut Rcc, psc: u16, arr: u16) -> Self {
                tim.init(rcc);

                let p = Self { tim };
                // Auto-reload preload enable
                p.tim.ctlr1.set_arpe();
                p.tim.psc.write_psc(psc as u32);
                p.tim.atrlr.write_atrlr(arr as u32);
                p.tim.cnt.write_cnt(0);
                p
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                })
            }

            /// Start the counter (must be called before PWM is output).
            #[inline(always)]
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            #[inline(always)]
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Set the auto-reload (period) value.
            #[inline(always)]
            pub fn set_period(&mut self, arr: u16) {
                self.tim.atrlr.write_atrlr(arr as u32);
            }

            /// Enable PWM output on channel 1 with the given compare value.
            pub fn enable_ch1(&mut self, compare: u16) {
                self.tim.chctlr1_output.write_oc1m(0b110); // PWM mode 1
                self.tim.chctlr1_output.set_oc1pe(); // preload enable
                self.tim.chctlr1_output.write_cc1s(0); // output
                self.tim.ch1cvr.write_ch1cvr(compare as u32);
                self.tim.ccer.set_cc1e();
                self.tim.bdtr.set_moe(); // main output enable
            }

            /// Enable PWM output on channel 2.
            pub fn enable_ch2(&mut self, compare: u16) {
                self.tim.chctlr1_output.write_oc2m(0b110);
                self.tim.chctlr1_output.set_oc2pe();
                self.tim.chctlr1_output.write_cc2s(0);
                self.tim.ch2cvr.write_ch2cvr(compare as u32);
                self.tim.ccer.set_cc2e();
                self.tim.bdtr.set_moe();
            }

            /// Enable PWM output on channel 3.
            pub fn enable_ch3(&mut self, compare: u16) {
                self.tim.chctlr2_output.write_oc3m(0b110);
                self.tim.chctlr2_output.set_oc3pe();
                self.tim.chctlr2_output.write_cc3s(0);
                self.tim.ch3cvr.write_ch3cvr(compare as u32);
                self.tim.ccer.set_cc3e();
                self.tim.bdtr.set_moe();
            }

            /// Enable PWM output on channel 4.
            pub fn enable_ch4(&mut self, compare: u16) {
                self.tim.chctlr2_output.write_oc4m(0b110);
                self.tim.chctlr2_output.set_oc4pe();
                self.tim.chctlr2_output.write_cc4s(0);
                self.tim.ch4cvr.write_ch4cvr(compare as u32);
                self.tim.ccer.set_cc4e();
                self.tim.bdtr.set_moe();
            }

            /// Set the compare value of channel 1.
            #[inline(always)]
            pub fn set_ch1_compare(&mut self, compare: u16) {
                self.tim.ch1cvr.write_ch1cvr(compare as u32);
            }

            /// Set the compare value of channel 2.
            #[inline(always)]
            pub fn set_ch2_compare(&mut self, compare: u16) {
                self.tim.ch2cvr.write_ch2cvr(compare as u32);
            }

            /// Set the compare value of channel 3.
            #[inline(always)]
            pub fn set_ch3_compare(&mut self, compare: u16) {
                self.tim.ch3cvr.write_ch3cvr(compare as u32);
            }

            /// Set the compare value of channel 4.
            #[inline(always)]
            pub fn set_ch4_compare(&mut self, compare: u16) {
                self.tim.ch4cvr.write_ch4cvr(compare as u32);
            }

            /// Enable the complementary output of channel 1 (active high).
            ///
            /// The complementary output shares `CH1CVR` with the normal
            /// channel, so both are driven by the same compare value.
            pub fn enable_ch1n(&mut self) {
                self.tim.ccer.clr_cc1np();
                self.tim.ccer.set_cc1ne();
                self.tim.bdtr.set_moe();
            }

            /// Enable the complementary output of channel 2 (active high).
            pub fn enable_ch2n(&mut self) {
                self.tim.ccer.clr_cc2np();
                self.tim.ccer.set_cc2ne();
                self.tim.bdtr.set_moe();
            }

            /// Enable the complementary output of channel 3 (active high).
            pub fn enable_ch3n(&mut self) {
                self.tim.ccer.clr_cc3np();
                self.tim.ccer.set_cc3ne();
                self.tim.bdtr.set_moe();
            }

            /// Set the complementary output polarity of channel 1.
            ///
            /// `true` selects active-high output; `false` selects active-low.
            pub fn set_ch1n_polarity(&mut self, active_high: bool) {
                if active_high {
                    self.tim.ccer.clr_cc1np();
                } else {
                    self.tim.ccer.set_cc1np();
                }
            }

            /// Set the dead-time generator value (`BDTR.DTG`).
            ///
            /// The dead-time in clock cycles follows the CH32X035 BDTR
            /// encoding: `0..=127` maps directly to 0..127 cycles, while
            /// `128..=255` scales with the timer clock divider.
            #[inline(always)]
            pub fn set_dead_time(&mut self, dtg: u8) {
                self.tim.bdtr.write_dtg(dtg as u32);
            }

            /// Enable the break input (`BDTR.BKE`).
            #[inline(always)]
            pub fn enable_break(&mut self) {
                self.tim.bdtr.set_bke();
            }

            /// Disable the break input.
            #[inline(always)]
            pub fn disable_break(&mut self) {
                self.tim.bdtr.clr_bke();
            }

            /// Set the break input polarity.
            ///
            /// `true` selects an active-high break input (`BKP = 0`);
            /// `false` selects active-low (`BKP = 1`).
            pub fn set_break_polarity(&mut self, active_high: bool) {
                if active_high {
                    self.tim.bdtr.clr_bkp();
                } else {
                    self.tim.bdtr.set_bkp();
                }
            }

            /// Enable automatic output re-enable after a break event
            /// (`BDTR.AOE`).
            #[inline(always)]
            pub fn enable_auto_output(&mut self) {
                self.tim.bdtr.set_aoe();
            }

            /// Enable one-pulse mode (`CTLR1.OPM`): the counter stops at the
            /// next update event instead of wrapping around.
            #[inline(always)]
            pub fn enable_one_pulse(&mut self) {
                self.tim.ctlr1.set_opm();
            }

            /// Disable one-pulse mode.
            #[inline(always)]
            pub fn disable_one_pulse(&mut self) {
                self.tim.ctlr1.clr_opm();
            }

            /// Consume the driver and return the underlying peripheral.
            #[inline(always)]
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer_pwm!(Timer1Pwm, pac::TIM1);
impl_timer_pwm!(Timer2Pwm, pac::TIM2);

/// Counting direction reported by an encoder interface.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub enum EncoderDirection {
    /// Counting up.
    Up,
    /// Counting down.
    Down,
}

/// Generate an input-capture driver (`Timer1Capture`, `Timer2Capture`).
///
/// Supports per-channel edge capture and a PWM-input mode in which channel 1
/// measures the period and channel 2 the pulse width.
macro_rules! impl_timer_capture {
    ($name:ident, $periph:ty, $module:ident) => {
        /// Input-capture driver
        pub struct $name {
            tim: $periph,
            #[allow(dead_code)]
            clocks: Clocks,
        }

        impl $name {
            /// Create a new capture driver, resetting and clock-enabling the
            /// peripheral.
            pub fn init(tim: $periph, rcc: &mut Rcc, clocks: Clocks) -> Self {
                tim.init(rcc);
                Self { tim, clocks }
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                    clocks: unsafe { Clocks::steal() },
                })
            }

            /// Set the prescaler value (`PSC`).
            #[inline(always)]
            pub fn set_prescaler(&mut self, psc: u16) {
                self.tim.psc.write_psc(psc as u32);
            }

            /// Set the auto-reload (period) value (`ATRLR`).
            #[inline(always)]
            pub fn set_period(&mut self, arr: u16) {
                self.tim.atrlr.write_atrlr(arr as u32);
            }

            /// Start the counter.
            #[inline(always)]
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            #[inline(always)]
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Configure channel 1 for direct input capture on `TI1`.
            ///
            /// `filter` is the `IC1F` digital-filter value (0..=15);
            /// `falling` selects a falling-edge trigger (rising edge
            /// otherwise).
            pub fn configure_ch1(&mut self, filter: u8, falling: bool) {
                self.tim.chctlr1_input().write_cc1s(0b01);
                self.tim.chctlr1_input().write_ic1f(filter as u32);
                self.tim.chctlr1_input().write_ic1psc(0);
                if falling {
                    self.tim.ccer.set_cc1p();
                } else {
                    self.tim.ccer.clr_cc1p();
                }
                self.tim.ccer.set_cc1e();
            }

            /// Configure channel 2 for indirect input capture on `TI2`.
            ///
            /// `filter` is the `IC2F` digital-filter value (0..=15);
            /// `falling` selects a falling-edge trigger (rising edge
            /// otherwise).
            pub fn configure_ch2(&mut self, filter: u8, falling: bool) {
                self.tim.chctlr1_input().write_cc2s(0b10);
                self.tim.chctlr1_input().write_ic2f(filter as u32);
                self.tim.chctlr1_input().write_ic2pcs(0);
                if falling {
                    self.tim.ccer.set_cc2p();
                } else {
                    self.tim.ccer.clr_cc2p();
                }
                self.tim.ccer.set_cc2e();
            }

            /// Configure PWM-input mode.
            ///
            /// Channel 1 (direct, rising edge) measures the period and
            /// channel 2 (indirect, falling edge) the pulse width; the
            /// counter resets on every `TI1` rising edge.
            pub fn enable_pwm_input(&mut self) {
                self.configure_ch1(0, false);
                self.configure_ch2(0, true);
                self.tim.smcfgr.write_ts(0b101); // TI1FP1
                self.tim.smcfgr.write_sms(0b100); // reset mode
                self.tim.smcfgr.set_msm();
            }

            /// Read the channel 1 capture value.
            #[inline(always)]
            pub fn capture_ch1(&self) -> u16 {
                self.tim.ch1cvr.ch1cvr() as u16
            }

            /// Read the channel 2 capture value.
            #[inline(always)]
            pub fn capture_ch2(&self) -> u16 {
                self.tim.ch2cvr.ch2cvr() as u16
            }

            /// Check whether the channel 1 capture flag is set.
            #[inline(always)]
            pub fn is_capture_flag_ch1(&self) -> bool {
                self.tim.intfr.cc1if()
            }

            /// Check whether the channel 2 capture flag is set.
            #[inline(always)]
            pub fn is_capture_flag_ch2(&self) -> bool {
                self.tim.intfr.cc2if()
            }

            /// Clear the channel 1 capture flag.
            #[inline(always)]
            pub fn clear_capture_flag_ch1(&mut self) {
                self.tim.intfr.write_bits(pac::$module::Intfr::CC1IF);
            }

            /// Clear the channel 2 capture flag.
            #[inline(always)]
            pub fn clear_capture_flag_ch2(&mut self) {
                self.tim.intfr.write_bits(pac::$module::Intfr::CC2IF);
            }

            /// Enable the channel 1 capture interrupt.
            #[inline(always)]
            pub fn enable_ch1_interrupt(&mut self) {
                self.tim.dmaintenr.set_cc1ie();
            }

            /// Disable the channel 1 capture interrupt.
            #[inline(always)]
            pub fn disable_ch1_interrupt(&mut self) {
                self.tim.dmaintenr.clr_cc1ie();
            }

            /// Enable the channel 2 capture interrupt.
            #[inline(always)]
            pub fn enable_ch2_interrupt(&mut self) {
                self.tim.dmaintenr.set_cc2ie();
            }

            /// Disable the channel 2 capture interrupt.
            #[inline(always)]
            pub fn disable_ch2_interrupt(&mut self) {
                self.tim.dmaintenr.clr_cc2ie();
            }

            /// Consume the driver and return the underlying peripheral.
            #[inline(always)]
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer_capture!(Timer1Capture, pac::TIM1, tim1);
impl_timer_capture!(Timer2Capture, pac::TIM2, tim2);

/// Generate a quadrature encoder interface driver (`Timer1Encoder`,
/// `Timer2Encoder`).
///
/// Uses encoder interface mode 3 (`SMS = 0b011`), counting on both `TI1` and
/// `TI2` edges, with the two encoder inputs mapped to channels 1 and 2.
macro_rules! impl_timer_encoder {
    ($name:ident, $periph:ty, $module:ident) => {
        /// Quadrature encoder interface driver
        pub struct $name {
            tim: $periph,
        }

        impl $name {
            /// Create a new encoder driver, resetting and clock-enabling the
            /// peripheral and configuring encoder interface mode.
            pub fn init(tim: $periph, rcc: &mut Rcc, psc: u16, arr: u16) -> Self {
                tim.init(rcc);

                let p = Self { tim };
                p.tim.ctlr1.set_arpe();
                p.tim.psc.write_psc(psc as u32);
                p.tim.atrlr.write_atrlr(arr as u32);
                p.tim.cnt.write_cnt(0);
                // Encoder interface mode 3: count on both TI1 and TI2 edges.
                p.tim.smcfgr.write_sms(0b011);
                // Channels 1 and 2 as direct inputs, no filter.
                p.tim.chctlr1_input().write_cc1s(0b01);
                p.tim.chctlr1_input().write_cc2s(0b01);
                p.tim.chctlr1_input().write_ic1f(0);
                p.tim.chctlr1_input().write_ic2f(0);
                // Trigger on both edges (clear CC1P / CC2P).
                p.tim.ccer.clr_cc1p();
                p.tim.ccer.clr_cc2p();
                p
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    tim: unsafe { <$periph>::steal() },
                })
            }

            /// Start the counter.
            #[inline(always)]
            pub fn start(&mut self) {
                self.tim.ctlr1.set_cen();
            }

            /// Stop the counter.
            #[inline(always)]
            pub fn stop(&mut self) {
                self.tim.ctlr1.clr_cen();
            }

            /// Read the current encoder count.
            #[inline(always)]
            pub fn count(&self) -> u16 {
                self.tim.cnt.cnt() as u16
            }

            /// Current counting direction.
            #[inline]
            pub fn direction(&self) -> EncoderDirection {
                if self.tim.ctlr1.dir() {
                    EncoderDirection::Down
                } else {
                    EncoderDirection::Up
                }
            }

            /// Clear the update interrupt flag.
            #[inline(always)]
            pub fn clear_update_flag(&mut self) {
                self.tim.intfr.write_bits(pac::$module::Intfr::UIF);
            }

            /// Check whether the update interrupt flag is set.
            #[inline(always)]
            pub fn is_update_flag(&self) -> bool {
                self.tim.intfr.uif()
            }

            /// Enable the update interrupt.
            #[inline(always)]
            pub fn enable_update_interrupt(&mut self) {
                self.tim.dmaintenr.set_uie();
            }

            /// Disable the update interrupt.
            #[inline(always)]
            pub fn disable_update_interrupt(&mut self) {
                self.tim.dmaintenr.clr_uie();
            }

            /// Consume the driver and return the underlying peripheral.
            #[inline(always)]
            pub fn release(self) -> $periph {
                self.tim
            }
        }
    };
}

impl_timer_encoder!(Timer1Encoder, pac::TIM1, tim1);
impl_timer_encoder!(Timer2Encoder, pac::TIM2, tim2);
